/**
 * Simple in-memory Event Bus for publish/subscribe communication between services
 */

export interface EventPayload {
  [key: string]: unknown;
}

export type EventCallback = (payload: EventPayload) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Subscribe to an event by name
   */
  subscribe(eventName: string, callback: EventCallback): void {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, []);
    }
    this.subscribers.get(eventName)!.push(callback);
  }

  /**
   * Publish an event to all subscribers
   */
  publish(eventName: string, payload: EventPayload): void {
    const callbacks = this.subscribers.get(eventName);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event handler for ${eventName}:`, error);
        }
      });
    }
  }
}

export const eventBus = new EventBus();

/**
 * User Service - manages user data
 */

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();
  private nextId: number = 1;

  /**
   * Create a new user
   */
  createUser(name: string, email: string): User {
    const id = `user-${this.nextId++}`;
    const user: User = { id, name, email };
    this.users.set(id, user);
    return user;
  }

  /**
   * Get a user by ID
   */
  getUser(userId: string): User | undefined {
    return this.users.get(userId);
  }

  /**
   * Get all users
   */
  getAllUsers(): User[] {
    return Array.from(this.users.values());
  }

  /**
   * Update a user
   */
  updateUser(userId: string, name?: string, email?: string): User | undefined {
    const user = this.users.get(userId);
    if (!user) return undefined;

    if (name !== undefined) user.name = name;
    if (email !== undefined) user.email = email;

    this.users.set(userId, user);
    return user;
  }

  /**
   * Delete a user
   */
  deleteUser(userId: string): boolean {
    return this.users.delete(userId);
  }

  /**
   * Check if a user exists
   */
  userExists(userId: string): boolean {
    return this.users.has(userId);
  }
}

export const userService = new UserService();

/**
 * Project Service - manages projects and their members
 */

export interface Project {
  id: string;
  name: string;
  description: string;
  members: string[]; // user IDs
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();
  private nextId: number = 1;

  /**
   * Create a new project
   */
  createProject(name: string, description: string, creatorId?: string): Project {
    const id = `project-${this.nextId++}`;
    const members = creatorId ? [creatorId] : [];
    const project: Project = { id, name, description, members };
    this.projects.set(id, project);
    return project;
  }

  /**
   * Get a project by ID
   */
  getProject(projectId: string): Project | undefined {
    return this.projects.get(projectId);
  }

  /**
   * Get all projects
   */
  getAllProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  /**
   * Update a project
   */
  updateProject(projectId: string, name?: string, description?: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;

    if (name !== undefined) project.name = name;
    if (description !== undefined) project.description = description;

    this.projects.set(projectId, project);
    return project;
  }

  /**
   * Delete a project
   */
  deleteProject(projectId: string): boolean {
    return this.projects.delete(projectId);
  }

  /**
   * Add a member to a project
   */
  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;

    if (!project.members.includes(userId)) {
      project.members.push(userId);
      this.projects.set(projectId, project);
    }

    return project;
  }

  /**
   * Remove a member from a project
   */
  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;

    project.members = project.members.filter(id => id !== userId);
    this.projects.set(projectId, project);

    return project;
  }

  /**
   * Check if a project exists
   */
  projectExists(projectId: string): boolean {
    return this.projects.has(projectId);
  }
}

export const projectService = new ProjectService();

/**
 * Task Service - manages tasks within projects
 */

import { eventBus } from './event-bus.js';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId?: string;
}

const VALID_STATUS_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  'todo': ['in-progress', 'done'],
  'in-progress': ['todo', 'done'],
  'done': ['todo', 'in-progress'],
};

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private nextId: number = 1;

  /**
   * Create a new task
   */
  createTask(projectId: string, title: string, description: string): Task {
    const id = `task-${this.nextId++}`;
    const task: Task = {
      id,
      projectId,
      title,
      description,
      status: 'todo',
    };
    this.tasks.set(id, task);
    return task;
  }

  /**
   * Get a task by ID
   */
  getTask(taskId: string): Task | undefined {
    return this.tasks.get(taskId);
  }

  /**
   * Get all tasks (optionally filtered by project)
   */
  getAllTasks(projectId?: string): Task[] {
    const allTasks = Array.from(this.tasks.values());
    if (projectId) {
      return allTasks.filter(task => task.projectId === projectId);
    }
    return allTasks;
  }

  /**
   * Update a task
   */
  updateTask(taskId: string, title?: string, description?: string): Task | undefined {
    const task = this.tasks.get(taskId);
    if (!task) return undefined;

    if (title !== undefined) task.title = title;
    if (description !== undefined) task.description = description;

    this.tasks.set(taskId, task);
    return task;
  }

  /**
   * Delete a task
   */
  deleteTask(taskId: string): boolean {
    return this.tasks.delete(taskId);
  }

  /**
   * Assign a task to a user
   */
  assignTask(taskId: string, userId: string): Task | undefined {
    const task = this.tasks.get(taskId);
    if (!task) return undefined;

    const oldAssignee = task.assigneeId;
    task.assigneeId = userId;
    this.tasks.set(taskId, task);

    // Publish event for notification service
    eventBus.publish('task.assigned', {
      taskId,
      userId,
      taskTitle: task.title,
      previousAssigneeId: oldAssignee,
    });

    return task;
  }

  /**
   * Change task status with validation
   */
  changeStatus(taskId: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(taskId);
    if (!task) return undefined;

    const oldStatus = task.status;

    // Validate status transition
    if (!VALID_STATUS_TRANSITIONS[oldStatus].includes(newStatus)) {
      throw new Error(`Cannot transition from ${oldStatus} to ${newStatus}`);
    }

    task.status = newStatus;
    this.tasks.set(taskId, task);

    // Publish event for notification service
    eventBus.publish('task.statusChanged', {
      taskId,
      oldStatus,
      newStatus,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
    });

    return task;
  }

  /**
   * Check if a task exists
   */
  taskExists(taskId: string): boolean {
    return this.tasks.has(taskId);
  }
}

export const taskService = new TaskService();

/**
 * Comment Service - manages comments on tasks
 */

import { eventBus } from './event-bus.js';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  text: string;
  timestamp: number;
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();
  private nextId: number = 1;

  /**
   * Create a new comment
   */
  createComment(taskId: string, authorId: string, text: string): Comment {
    const id = `comment-${this.nextId++}`;
    const comment: Comment = {
      id,
      taskId,
      authorId,
      text,
      timestamp: Date.now(),
    };
    this.comments.set(id, comment);

    // Publish event for notification service
    eventBus.publish('comment.added', {
      commentId: id,
      taskId,
      authorId,
      text,
      timestamp: comment.timestamp,
    });

    return comment;
  }

  /**
   * Get a comment by ID
   */
  getComment(commentId: string): Comment | undefined {
    return this.comments.get(commentId);
  }

  /**
   * Get all comments (optionally filtered by task)
   */
  getAllComments(taskId?: string): Comment[] {
    const allComments = Array.from(this.comments.values());
    if (taskId) {
      return allComments.filter(comment => comment.taskId === taskId);
    }
    return allComments;
  }

  /**
   * Delete a comment
   */
  deleteComment(commentId: string): boolean {
    return this.comments.delete(commentId);
  }

  /**
   * Check if a comment exists
   */
  commentExists(commentId: string): boolean {
    return this.comments.has(commentId);
  }
}

export const commentService = new CommentService();

/**
 * Notification Service - manages notifications for users
 * Listens to events from other services and creates notifications
 */

import { eventBus } from './event-bus.js';
import { taskService } from './task-service.js';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();
  private nextId: number = 1;

  constructor() {
    this.setupEventListeners();
  }

  /**
   * Set up event listeners for various events
   */
  private setupEventListeners(): void {
    // Listen for task assignment events
    eventBus.subscribe('task.assigned', (payload) => {
      const { userId, taskTitle } = payload;
      this.createNotification(
        userId,
        `You have been assigned to task: "${taskTitle}"`
      );
    });

    // Listen for task status change events
    eventBus.subscribe('task.statusChanged', (payload) => {
      const { newStatus, taskTitle, assigneeId } = payload;
      if (assigneeId) {
        this.createNotification(
          assigneeId,
          `Task "${taskTitle}" status changed to: ${newStatus}`
        );
      }
    });

    // Listen for comment added events
    eventBus.subscribe('comment.added', (payload) => {
      const { taskId, authorId } = payload;
      const task = taskService.getTask(taskId);
      if (task && task.assigneeId && task.assigneeId !== authorId) {
        this.createNotification(
          task.assigneeId,
          `A comment was added to your task: "${task.title}"`
        );
      }
    });
  }

  /**
   * Create a new notification
   */
  private createNotification(userId: string, message: string): Notification {
    const id = `notification-${this.nextId++}`;
    const notification: Notification = {
      id,
      userId,
      message,
      read: false,
      timestamp: Date.now(),
    };
    this.notifications.set(id, notification);
    return notification;
  }

  /**
   * Get a notification by ID
   */
  getNotification(notificationId: string): Notification | undefined {
    return this.notifications.get(notificationId);
  }

  /**
   * Get all notifications (optionally filtered by user)
   */
  getAllNotifications(userId?: string): Notification[] {
    const allNotifications = Array.from(this.notifications.values());
    if (userId) {
      return allNotifications.filter(notif => notif.userId === userId);
    }
    return allNotifications;
  }

  /**
   * Mark a notification as read
   */
  markAsRead(notificationId: string): Notification | undefined {
    const notification = this.notifications.get(notificationId);
    if (!notification) return undefined;

    notification.read = true;
    this.notifications.set(notificationId, notification);
    return notification;
  }

  /**
   * Check if a notification exists
   */
  notificationExists(notificationId: string): boolean {
    return this.notifications.has(notificationId);
  }
}

export const notificationService = new NotificationService();

/**
 * API Router - handles HTTP requests and routes them to appropriate services
 */

import { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { userService } from './user-service.js';
import { projectService } from './project-service.js';
import { taskService } from './task-service.js';
import { commentService } from './comment-service.js';
import { notificationService } from './notification-service.js';

export class APIRouter {
  async handleRequest(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url || '', `http://${req.headers.host}`);
    const pathname = url.pathname;
    const method = req.method || 'GET';

    try {
      // Users routes
      if (pathname === '/users' && method === 'GET') {
        return this.getAllUsers(res);
      }
      if (pathname === '/users' && method === 'POST') {
        return this.createUser(req, res);
      }
      if (pathname.match(/^\/users\/[^/]+$/) && method === 'GET') {
        const userId = pathname.split('/')[2];
        return this.getUser(res, userId);
      }
      if (pathname.match(/^\/users\/[^/]+$/) && method === 'PUT') {
        const userId = pathname.split('/')[2];
        return this.updateUser(req, res, userId);
      }
      if (pathname.match(/^\/users\/[^/]+$/) && method === 'DELETE') {
        const userId = pathname.split('/')[2];
        return this.deleteUser(res, userId);
      }

      // Projects routes
      if (pathname === '/projects' && method === 'GET') {
        return this.getAllProjects(res);
      }
      if (pathname === '/projects' && method === 'POST') {
        return this.createProject(req, res);
      }
      if (pathname.match(/^\/projects\/[^/]+$/) && method === 'GET') {
        const projectId = pathname.split('/')[2];
        return this.getProject(res, projectId);
      }
      if (pathname.match(/^\/projects\/[^/]+$/) && method === 'PUT') {
        const projectId = pathname.split('/')[2];
        return this.updateProject(req, res, projectId);
      }
      if (pathname.match(/^\/projects\/[^/]+$/) && method === 'DELETE') {
        const projectId = pathname.split('/')[2];
        return this.deleteProject(res, projectId);
      }

      // Projects members routes
      if (pathname.match(/^\/projects\/[^/]+\/members$/) && method === 'POST') {
        const projectId = pathname.split('/')[2];
        return this.addMember(req, res, projectId);
      }
      if (pathname.match(/^\/projects\/[^/]+\/members\/[^/]+$/) && method === 'DELETE') {
        const parts = pathname.split('/');
        const projectId = parts[2];
        const userId = parts[4];
        return this.removeMember(res, projectId, userId);
      }

      // Tasks routes
      if (pathname === '/tasks' && method === 'GET') {
        const projectId = url.searchParams.get('projectId') || undefined;
        return this.getAllTasks(res, projectId);
      }
      if (pathname === '/tasks' && method === 'POST') {
        return this.createTask(req, res);
      }
      if (pathname.match(/^\/tasks\/[^/]+$/) && method === 'GET') {
        const taskId = pathname.split('/')[2];
        return this.getTask(res, taskId);
      }
      if (pathname.match(/^\/tasks\/[^/]+$/) && method === 'PUT') {
        const taskId = pathname.split('/')[2];
        return this.updateTask(req, res, taskId);
      }
      if (pathname.match(/^\/tasks\/[^/]+$/) && method === 'DELETE') {
        const taskId = pathname.split('/')[2];
        return this.deleteTask(res, taskId);
      }

      // Task status route
      if (pathname.match(/^\/tasks\/[^/]+\/status$/) && method === 'PUT') {
        const taskId = pathname.split('/')[2];
        return this.changeTaskStatus(req, res, taskId);
      }

      // Task assign route
      if (pathname.match(/^\/tasks\/[^/]+\/assign$/) && method === 'PUT') {
        const taskId = pathname.split('/')[2];
        return this.assignTask(req, res, taskId);
      }

      // Comments routes
      if (pathname === '/comments' && method === 'GET') {
        const taskId = url.searchParams.get('taskId') || undefined;
        return this.getAllComments(res, taskId);
      }
      if (pathname === '/comments' && method === 'POST') {
        return this.createComment(req, res);
      }
      if (pathname.match(/^\/comments\/[^/]+$/) && method === 'GET') {
        const commentId = pathname.split('/')[2];
        return this.getComment(res, commentId);
      }
      if (pathname.match(/^\/comments\/[^/]+$/) && method === 'DELETE') {
        const commentId = pathname.split('/')[2];
        return this.deleteComment(res, commentId);
      }

      // Notifications routes
      if (pathname === '/notifications' && method === 'GET') {
        const userId = url.searchParams.get('userId') || undefined;
        return this.getAllNotifications(res, userId);
      }
      if (pathname.match(/^\/notifications\/[^/]+\/read$/) && method === 'PUT') {
        const notificationId = pathname.split('/')[2];
        return this.markNotificationAsRead(res, notificationId);
      }

      // 404 Not Found
      this.sendJson(res, 404, { error: 'Not Found' });
    } catch (error) {
      console.error('Error handling request:', error);
      this.sendJson(res, 500, { error: 'Internal Server Error' });
    }
  }

  // Utility methods
  private async readJsonBody(req: IncomingMessage): Promise<unknown> {
    return new Promise((resolve, reject) => {
      let body = '';
      req.on('data', chunk => {
        body += chunk.toString();
      });
      req.on('end', () => {
        try {
          resolve(body ? JSON.parse(body) : {});
        } catch (error) {
          reject(error);
        }
      });
      req.on('error', reject);
    });
  }

  private sendJson(res: ServerResponse, statusCode: number, data: unknown): void {
    res.writeHead(statusCode, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(data));
  }

  // Users handlers
  private getAllUsers(res: ServerResponse): void {
    const users = userService.getAllUsers();
    this.sendJson(res, 200, users);
  }

  private async createUser(req: IncomingMessage, res: ServerResponse): Promise<void> {
    try {
      const body = (await this.readJsonBody(req)) as Record<string, unknown>;
      const { name, email } = body;
      if (!name || !email) {
        return this.sendJson(res, 400, { error: 'Missing name or email' });
      }
      const user = userService.createUser(String(name), String(email));
      this.sendJson(res, 201, user);
    } catch (error) {
      this.sendJson(res, 400, { error: 'Invalid request' });
    }
  }

  private getUser(res: ServerResponse, userId: string): void {
    const user = userService.getUser(userId);
    if (!user) {
      return this.sendJson(res, 404, { error: 'User not found' });
    }
    this.sendJson(res, 200, user);
  }

  private async updateUser(
    req: IncomingMessage,
    res: ServerResponse,
    userId: string
  ): Promise<void> {
    try {
      const body = (await this.readJsonBody(req)) as Record<string, unknown>;
      const user = userService.updateUser(userId, body.name as string, body.email as string);
      if (!user) {
        return this.sendJson(res, 404, { error: 'User not found' });
      }
      this.sendJson(res, 200, user);
    } catch (error) {
      this.sendJson(res, 400, { error: 'Invalid request' });
    }
  }

  private deleteUser(res: ServerResponse, userId: string): void {
    const deleted = userService.deleteUser(userId);
    if (!deleted) {
      return this.sendJson(res, 404, { error: 'User not found' });
    }
    this.sendJson(res, 200, { message: 'User deleted' });
  }

  // Projects handlers
  private getAllProjects(res: ServerResponse): void {
    const projects = projectService.getAllProjects();
    this.sendJson(res, 200, projects);
  }

  private async createProject(req: IncomingMessage, res: ServerResponse): Promise<void> {
    try {
      const body = (await this.readJsonBody(req)) as Record<string, unknown>;
      const { name, description, creatorId } = body;
      if (!name) {
        return this.sendJson(res, 400, { error: 'Missing name' });
      }
      const project = projectService.createProject(
        String(name),
        String(description || ''),
        creatorId as string | undefined
      );
      this.sendJson(res, 201, project);
    } catch (error) {
      this.sendJson(res, 400, { error: 'Invalid request' });
    }
  }

  private getProject(res: ServerResponse, projectId: string): void {
    const project = projectService.getProject(projectId);
    if (!project) {
      return this.sendJson(res, 404, { error: 'Project not found' });
    }
    this.sendJson(res, 200, project);
  }

  private async updateProject(
    req: IncomingMessage,
    res: ServerResponse,
    projectId: string
  ): Promise<void> {
    try {
      const body = (await this.readJsonBody(req)) as Record<string, unknown>;
      const project = projectService.updateProject(
        projectId,
        body.name as string,
        body.description as string
      );
      if (!project) {
        return this.sendJson(res, 404, { error: 'Project not found' });
      }
      this.sendJson(res, 200, project);
    } catch (error) {
      this.sendJson(res, 400, { error: 'Invalid request' });
    }
  }

  private deleteProject(res: ServerResponse, projectId: string): void {
    const deleted = projectService.deleteProject(projectId);
    if (!deleted) {
      return this.sendJson(res, 404, { error: 'Project not found' });
    }
    this.sendJson(res, 200, { message: 'Project deleted' });
  }

  private async addMember(
    req: IncomingMessage,
    res: ServerResponse,
    projectId: string
  ): Promise<void> {
    try {
      const body = (await this.readJsonBody(req)) as Record<string, unknown>;
      const { userId } = body;
      if (!userId) {
        return this.sendJson(res, 400, { error: 'Missing userId' });
      }
      const project = projectService.addMember(projectId, String(userId));
      if (!project) {
        return this.sendJson(res, 404, { error: 'Project not found' });
      }
      this.sendJson(res, 200, project);
    } catch (error) {
      this.sendJson(res, 400, { error: 'Invalid request' });
    }
  }

  private removeMember(res: ServerResponse, projectId: string, userId: string): void {
    const project = projectService.removeMember(projectId, userId);
    if (!project) {
      return this.sendJson(res, 404, { error: 'Project not found' });
    }
    this.sendJson(res, 200, project);
  }

  // Tasks handlers
  private getAllTasks(res: ServerResponse, projectId?: string): void {
    const tasks = taskService.getAllTasks(projectId);
    this.sendJson(res, 200, tasks);
  }

  private async createTask(req: IncomingMessage, res: ServerResponse): Promise<void> {
    try {
      const body = (await this.readJsonBody(req)) as Record<string, unknown>;
      const { projectId, title, description } = body;
      if (!projectId || !title) {
        return this.sendJson(res, 400, { error: 'Missing projectId or title' });
      }
      const task = taskService.createTask(
        String(projectId),
        String(title),
        String(description || '')
      );
      this.sendJson(res, 201, task);
    } catch (error) {
      this.sendJson(res, 400, { error: 'Invalid request' });
    }
  }

  private getTask(res: ServerResponse, taskId: string): void {
    const task = taskService.getTask(taskId);
    if (!task) {
      return this.sendJson(res, 404, { error: 'Task not found' });
    }
    this.sendJson(res, 200, task);
  }

  private async updateTask(
    req: IncomingMessage,
    res: ServerResponse,
    taskId: string
  ): Promise<void> {
    try {
      const body = (await this.readJsonBody(req)) as Record<string, unknown>;
      const task = taskService.updateTask(
        taskId,
        body.title as string,
        body.description as string
      );
      if (!task) {
        return this.sendJson(res, 404, { error: 'Task not found' });
      }
      this.sendJson(res, 200, task);
    } catch (error) {
      this.sendJson(res, 400, { error: 'Invalid request' });
    }
  }

  private deleteTask(res: ServerResponse, taskId: string): void {
    const deleted = taskService.deleteTask(taskId);
